type initStateType = {
    themeId: number
}

const initState: initStateType = {
    themeId: 1,
}
type changeThemeIdAT = {
    type: 'SET_THEME_ID'
    id: number
}
type ActionType = changeThemeIdAT
export const themeReducer = (state = initState, action: ActionType): initStateType => { // fix any
    switch (action.type) {
        case 'SET_THEME_ID':
            return {...state, themeId: action.id}

        default:
            return state
    }
}

export const changeThemeId = (id: number): changeThemeIdAT => ({type: 'SET_THEME_ID', id}) // fix any
